/* 符号类示例按类别索引：{ symbols: {文件名: 文本}, emoji: {...}, kaomoji: {...} }。
 * 符号页的「载入示例」按当前类别取这里，而不是按文件名 ——
 * 文件名是给人看的，类别才是程序的键（改名不该让功能失效）。 */
FE.SYMBOL_EXAMPLE_FILES = (function () {
  var out = { symbols: {}, emoji: {}, kaomoji: {} };
  var files = FE.EXAMPLE_FILES, m = FE.EXAMPLE_META;
  Object.keys(files).forEach(function (n) {
    var info = m[n];
    if (!info || info.kind !== "symbol") return;
    var k = out[info.symbolKind] ? info.symbolKind : "symbols";
    out[k][n] = files[n];
  });
  return out;
})();
